// Copies protocol/h2h/card.json and protocol/h2h/community-tools.json into src/h2h/data.generated.ts,
// so the node build and the dashboard bundle serve exactly the files in protocol/h2h/.
// Run after editing either JSON file: npm run build:h2h-data. A test fails if this file is stale.
import { readFileSync, writeFileSync } from "node:fs";

const card = JSON.parse(readFileSync("protocol/h2h/card.json", "utf8"));
const tools = JSON.parse(readFileSync("protocol/h2h/community-tools.json", "utf8"));
const text = [
  "/* Generated by npm run build:h2h-data from protocol/h2h/card.json and protocol/h2h/community-tools.json. Do not edit. */",
  `export const H2H_CARD: unknown = ${JSON.stringify(card, null, 2)};`,
  "",
  `export const H2H_COMMUNITY_TOOLS: unknown = ${JSON.stringify(tools, null, 2)};`,
  "",
].join("\n");
writeFileSync("src/h2h/data.generated.ts", text);
console.log("Wrote src/h2h/data.generated.ts");
